/* ============================================================
   MALACCA ENGINE
   PDF extraction, Supply Chain export, Cost Break Down merge,
   and Malacca-specific UI wiring (no password gate).
   Depends on: shared.js (homeView)
   ============================================================ */
/* ============================================================
   MALACCA — PDF EXTRACTION ENGINE
   ============================================================ */
const MALACCA_TEMPLATE_B64 = "";

// Column x-boundaries (points, PDF user space) derived from the Malacca BOM
// table header row (Placement / Component Name / Material Type / Material /
// Reference No. / Supplier / Nominated? / Color / Comments-SM / Size /
// Consumption / Article UOM / Cuttable Width / Cuttable Width-Color /
// Comments-Supplier).
// Fallback column boundaries (points, PDF user space), calibrated against
// the original single-colorway sample with no Finish/Price columns. Used
// only if a page's own header row can't be parsed for some reason.
const MALACCA_COLUMNS_FALLBACK = [
  { key: 'placement',           max: 58.5 },
  { key: 'componentName',       max: 118.05 },
  { key: 'materialType',        max: 165.7 },
  { key: 'material',            max: 219.3 },
  { key: 'referenceNo',         max: 272.9 },
  { key: 'supplier',            max: 326.5 },
  { key: 'nominated',           max: 380.15 },
  { key: 'color',               max: 421.85 },
  { key: 'commentsSM',          max: 463.55 },
  { key: 'size',                max: 511.2 },
  { key: 'consumption',         max: 558.8 },
  { key: 'articleUOM',          max: 630.0 },
  { key: 'cuttableWidth',       max: 685.0 },
  { key: 'cuttableWidthColor',  max: 715.0 },
  { key: 'commentsSupplier',    max: Infinity },
];

// These are the columns the merge engine actually reads downstream
// (buildMalaccaCBD / buildMalaccaSupplyChain never touch nominated, color,
// commentsSM, or commentsSupplier). Any *other* column a given tech pack
// happens to include — a 2nd/3rd colorway, "Finish", "Price" — varies
// between products and isn't needed, so it's fine for that data to fall
// into whichever bucket its x lands in; it's discarded either way. What
// matters is that these required columns stay correctly anchored no
// matter how many extra columns are inserted around them.
const MALACCA_REQUIRED_COLUMNS = [
  'placement', 'componentName', 'materialType', 'material',
  'referenceNo', 'supplier', 'size', 'consumption', 'articleUOM',
];

// Derives this page's column boundaries from its own header row instead of
// assuming a fixed pixel layout — some Malacca tech packs add a second (or
// third) colorway column, or "Finish"/"Price" columns, which shifts every
// column after them. Anchoring on each required column's own label makes
// extraction immune to how many extra columns sit around it.
function deriveMalaccaColumnBoundaries(headerItems) {
  function anchorX(text, occurrence) {
    const matches = headerItems.filter(it => it.text === text).sort((a, b) => a.x - b.x);
    return matches[occurrence] !== undefined ? matches[occurrence].x : null;
  }
  const candidates = [
    ['placement',          anchorX('Placement', 0)],
    ['componentName',      anchorX('Compone', 0)],
    ['materialType',       anchorX('Material', 0)], // "Material Type" always precedes "Material"
    ['material',           anchorX('Material', 1)],
    ['referenceNo',        anchorX('Reference', 0)],
    ['supplier',           anchorX('Supplier', 0)],
    ['nominated',          anchorX('Nominate', 0)],
    ['commentsSM',         anchorX('Comment', 0)],
    ['finish',             anchorX('Finish', 0)],   // optional
    ['size',               anchorX('Size', 0)],
    ['consumption',        anchorX('Consump', 0)],
    ['articleUOM',         anchorX('Article', 0)],
    ['price',              anchorX('Price', 0)],    // optional
    ['cuttableWidth',      anchorX('Cuttable', 0)], // "Cuttable Width" always precedes "-Color"
    ['cuttableWidthColor', anchorX('Cuttable', 1)],
  ];

  const present = candidates.filter(([, x]) => x !== null);
  const foundKeys = new Set(present.map(([key]) => key));
  for (const key of MALACCA_REQUIRED_COLUMNS) {
    if (!foundKeys.has(key)) return null; // couldn't parse this header — caller falls back
  }

  present.sort((a, b) => a[1] - b[1]);
  return present.map(([key, x], i) => ({
    key,
    // Biased toward the next anchor (60% of the gap) rather than a strict
    // midpoint: column labels are short and left-aligned, but the actual
    // data (e.g. a long Placement description) can run wider than the
    // label alone suggests. A strict midpoint risks classifying the tail
    // of a long value into the next column.
    max: i + 1 < present.length ? x + (present[i + 1][1] - x) * 0.6 : Infinity,
  }));
}

function classifyMalaccaColumn(x, columns) {
  const cols = columns || MALACCA_COLUMNS_FALLBACK;
  for (const c of cols) if (x < c.max) return c.key;
  return cols.length ? cols[cols.length - 1].key : 'commentsSupplier';
}

const MALACCA_SECTION_RE = /^Section:\s*(\d+)\s*-\s*(.+)$/;
const MALACCA_CONSUMPTION_RE = /^\d+\.\d+$/;

// Cover page (page 1) header table anchors — this is a fixed 4-column
// label/value table repeated (with the same values) on every page, e.g.:
//   Col1: Licensor Product Code: | Gender: | Production Manager: | Destination:
//   Col2: Style:                 | Brand:  | SM Tech Contact:
//   Col3: Season Name:           | Age:    | PSD Seasonal Size 1 Values:
//   Col4: Date                   | Spec Stage: | PSD Seasonal Size 2 Values:
// Column boundaries are derived at runtime from these label anchors'
// x-positions (midpoint between adjacent columns), the same technique used
// for the BOM table's column boundaries — never hardcoded pixel values,
// since layouts can shift slightly between tech pack exports.
const MALACCA_COVER_COLUMN_ANCHORS = [
  ['Gender:', 'Production', 'Destination:'],
  ['Style:', 'Brand:'],
  ['Season', 'Age:'],
  ['Date', 'Spec'],
];

function malaccaClusterLines(items, tol) {
  const sorted = [...items].sort((a, b) => a.y - b.y || a.x - b.x);
  const lines = [];
  for (const it of sorted) {
    const last = lines[lines.length - 1];
    let line = last && Math.abs(last.y - it.y) < tol ? last : null;
    if (!line) { line = { y: it.y, items: [] }; lines.push(line); }
    line.items.push(it);
  }
  for (const l of lines) l.items.sort((a, b) => a.x - b.x);
  return lines;
}

function extractMalaccaCoverInfo(items) {
  // Header zone: below the very top page-label line (y<=12, handled
  // separately as topLabel) and above "TABLE OF CONTENTS".
  const headerItems = items.filter(it => it.y > 13 && it.y < 100);
  if (!headerItems.length) return null;

  // Derive each column's starting x from its known label anchors.
  const colStart = MALACCA_COVER_COLUMN_ANCHORS.map(labels => {
    const xs = headerItems.filter(it => labels.includes(it.text)).map(it => it.x);
    return xs.length ? Math.min(...xs) : null;
  });
  if (colStart.some(x => x === null)) return null; // layout didn't match — bail out safely

  // Each column's label sits well to the left of its own value, and both
  // sit safely left of the *next* column's label — so the next column's
  // label start is a safe exclusive boundary. (A midpoint between the two
  // label starts is NOT safe here: a column's value can land right next to
  // that midpoint and get misclassified into the following column.)
  const boundaries = [colStart[1], colStart[2], colStart[3]];
  function col(x) {
    if (x < boundaries[0]) return 0;
    if (x < boundaries[1]) return 1;
    if (x < boundaries[2]) return 2;
    return 3;
  }

  const lines = malaccaClusterLines(headerItems, 2.5);
  const colTexts = ['', '', '', ''];
  for (const line of lines) {
    for (const it of line.items) {
      const c = col(it.x);
      colTexts[c] = (colTexts[c] ? colTexts[c] + ' ' : '') + it.text;
    }
  }

  const style = (colTexts[1].match(/Style:\s*(.+?)\s*Brand:/) || [])[1] || '';
  const brand = (colTexts[1].match(/Brand:\s*(.+?)\s*SM\b/) || [])[1] || '';
  const age = (colTexts[2].match(/Age:\s*(.+?)\s*PSD\b/) || [])[1] || '';
  const gender = (colTexts[0].match(/Gender:\s*(.+?)\s*Production\b/) || [])[1] || '';

  // Style is a leading style number followed by a free-text description
  // (e.g. "154969 Authentic Women's Fake Down Coats") — split so the
  // number and description can go to their own separate cells.
  const styleMatch = style.match(/^(\d+)\s+(.+)$/);
  const styleNo = styleMatch ? styleMatch[1] : style;
  const subclass = styleMatch ? styleMatch[2] : '';

  // Column 0's "Production Manager:" label wraps onto 2 lines ("Production"
  // / "Manager:") in parallel with its own value wrapping onto up to 3
  // lines ("Romanovskaya" / "Ekaterina" / "Vitalevna") at a slightly larger
  // x within the same column — concatenating the whole column's text in
  // reading order interleaves label and value fragments. Instead, split
  // column 0 into its label sub-column (narrow x range) and value
  // sub-column, then take the value items whose y falls between the
  // "Production" label and the next row's label ("Destination:").
  const col0Items = headerItems.filter(it => col(it.x) === 0);
  const col0LabelX = colStart[0];
  const col0ValueSplit = col0LabelX + 50; // small gap between label and value sub-columns
  const col0Label = col0Items.filter(it => it.x < col0ValueSplit);
  const col0Value = col0Items.filter(it => it.x >= col0ValueSplit);
  const prodItem = col0Label.find(it => it.text === 'Production');
  const destItem = col0Label.find(it => it.text === 'Destination:');
  let productionManager = '';
  if (prodItem && destItem) {
    productionManager = col0Value
      .filter(it => it.y >= prodItem.y - 1 && it.y < destItem.y - 1)
      .sort((a, b) => a.y - b.y || a.x - b.x)
      .map(it => it.text).join(' ').trim();
  }

  return { styleNo, subclass, brand, age, gender, productionManager };
}

// Every BOM page's fixed top-left label contains "BOM_" (e.g.
// "001 : BOM_154969_Tianyi_AW28 -- BOM: Colorway - Material Color") — every
// other page type (Cover, Detail Sketch, Graded Measurement, Technical
// Sketch, Construction Detail) doesn't, and some of those (Graded
// Measurement in particular) contain numeric-looking data that could
// otherwise be misread as BOM rows.
const MALACCA_BOM_PAGE_RE = /\bBOM[_:]/i;

// Tokens that make up the (multi-line) BOM table header/its wrapped
// fragments — used to skip header rows during extraction. Hoisted to a
// constant so it isn't reallocated on every line of every page.
const MALACCA_HEADER_FRAG_TOKENS = new Set(['t','Name','Type','No.','?','99','SM','on','UOM','Width','Width-','-Supplier','-','black']);

async function extractMalaccaPdf(file, onProgress) {
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;

  const sections = {}; // '01 - Fabric' -> [{...}, ...]
  let currentSection = null;
  let activeRow = null;
  let isBomPage = false;
  let styleNumber = null;
  let coverInfo = null;
  // Column boundaries derived from the table's own header row (see
  // deriveMalaccaColumnBoundaries) — persists across pages since some
  // tech packs only print the header once, on the table's first page.
  let columnBoundaries = null;
  let headerCollecting = false;
  let headerItemsBuf = [];
  let headerLinesCollected = 0;

  function blankCols() {
    return { placement: '', componentName: '', materialType: '', material: '',
      referenceNo: '', supplier: '', nominated: '', color: '', commentsSM: '',
      size: '', consumption: '', articleUOM: '', cuttableWidth: '', cuttableWidthColor: '', commentsSupplier: '' };
  }

  function flushRow() {
    if (activeRow && currentSection) {
      // discard placeholder/empty section rows (no real item — just the
      // section's default blank row, e.g. Sections 06/07 when unused)
      if (activeRow.placement || activeRow.componentName || activeRow.material) {
        sections[currentSection] = sections[currentSection] || [];
        sections[currentSection].push(activeRow);
      }
    }
    activeRow = null;
  }

  for (let p = 1; p <= pdf.numPages; p++) {
    onProgress && onProgress(p, pdf.numPages);
    const page = await pdf.getPage(p);
    const viewport = page.getViewport({ scale: 1 });
    const content = await page.getTextContent();

    const items = content.items
      .map(it => {
        const tx = pdfjsLib.Util.transform(viewport.transform, it.transform);
        return { text: it.str, x: tx[4], y: tx[5] };
      })
      .filter(it => it.text.trim().length > 0);

    // Page 1 (Cover Page) carries the brand/style/age/PM header info.
    if (p === 1) {
      coverInfo = extractMalaccaCoverInfo(items);
    }

    const topLabel = items.filter(it => it.y <= 12).sort((a, b) => a.x - b.x).map(i => i.text).join(' ');
    isBomPage = MALACCA_BOM_PAGE_RE.test(topLabel);
    if (!isBomPage) continue;
    if (!styleNumber) {
      const sm = topLabel.match(/BOM_(\d+)/i);
      if (sm) styleNumber = sm[1];
    }

    // 'Destination:' is part of the fixed header block repeated on every
    // page. Its y-position drifts depending on how many lines the other
    // header fields (e.g. Production Manager) wrap onto, so it can
    // occasionally land past the y>90 content cutoff below and leak into
    // a row's description — exclude it explicitly rather than by position.
    const content_items = items.filter(it => it.y > 90 && it.y < 585 && it.text !== 'Destination:');
    // content_items is sorted ascending by y (done inside
    // malaccaClusterLines), so once an item's y moves past the last
    // line's tolerance band it can never match an earlier line — this
    // gives O(n) grouping instead of O(n^2), and lines come out already
    // in ascending-y order.
    const lines = malaccaClusterLines(content_items, 2.5);

    for (const line of lines) {
      const lineText = line.items.map(i => i.text).join(' ').trim().replace(/\s+/g, ' ');

      const m = lineText.match(MALACCA_SECTION_RE);
      if (m) {
        const newSection = `${m[1]} - ${m[2]}`;
        // Some tech packs repeat "Section: X" at the top of a continuation
        // page when a section's table spans a page break. That's not a
        // real transition to a new section — don't flush the in-progress
        // row, since its wrapped continuation may still be coming.
        if (newSection !== currentSection) {
          flushRow();
          currentSection = newSection;
        }
        continue;
      }
      // The header row's column labels wrap across exactly 3 physical
      // lines (main row, continuation fragments, and a 3rd "Color" wrap
      // for Cuttable Width-Color) in every real tech pack examined — and
      // the *set* of columns varies between tech packs (some add a 2nd
      // colorway, Finish, Price). Collect those 3 lines unconditionally
      // (a fixed count, not a content-based guess — a guess like "does
      // this look like a data value" is fragile to exactly how the PDF's
      // text gets tokenized) and derive this table's column boundaries
      // from them instead of assuming a fixed pixel layout.
      if (line.items[0] && line.items[0].text === 'Placement' && line.items[0].x < 30) {
        headerCollecting = true;
        headerItemsBuf = [...line.items];
        headerLinesCollected = 1;
        continue;
      }
      if (headerCollecting) {
        if (headerLinesCollected < 3) {
          headerItemsBuf.push(...line.items);
          headerLinesCollected++;
          continue;
        }
        headerCollecting = false;
        columnBoundaries = deriveMalaccaColumnBoundaries(headerItemsBuf) || MALACCA_COLUMNS_FALLBACK;
      }
      // Defensive fallback for the rare case a header fragment line slips
      // through the collection above (e.g. header collection never
      // triggered on this page for some reason).
      if (line.items.length <= 4 && line.items.every(t => MALACCA_HEADER_FRAG_TOKENS.has(t.text))) continue;
      if (lineText === 'Color' && line.items[0].x > 670) continue;

      if (!currentSection) continue;

      const cols = blankCols();
      for (const it of line.items) {
        const key = classifyMalaccaColumn(it.x, columnBoundaries);
        cols[key] = (cols[key] ? cols[key] + ' ' : '') + it.text;
      }

      // pdf.js can split a single number like "0.0000" across multiple
      // text items (font-kerning artifacts in the source PDF), which get
      // rejoined above with a space (e.g. "0. 0000"). Strip whitespace
      // before testing so a fragmented consumption value still matches.
      const consumptionVal = cols.consumption.replace(/\s+/g, '');
      if (MALACCA_CONSUMPTION_RE.test(consumptionVal)) {
        flushRow();
        activeRow = {};
        for (const k of Object.keys(cols)) activeRow[k] = cols[k].trim();
        activeRow.consumption = consumptionVal; // use the whitespace-stripped value
      } else if (activeRow) {
        for (const k of Object.keys(cols)) {
          if (cols[k].trim()) activeRow[k] = (activeRow[k] ? activeRow[k] + ' ' : '') + cols[k].trim();
        }
      }
    }
  }
  flushRow();

  return { sections, styleNumber, coverInfo }; // sections: { '01 - Fabric': [...], '02 - Trims': [...], ... }
}

function malaccaLeadingNumber(material) {
  const m = (material || '').match(/^(\d+)/);
  return m ? m[1] : '';
}

function malaccaCleanText(s) {
  // collapse the odd extra spaces that appear when pdf.js splits a single
  // token across two text runs (e.g. "TW0000 1" -> "TW00001")
  return (s || '').replace(/(\d)\s+(?=\d)/g, '$1').trim();
}

/* ============================================================
   MALACCA — "FOR SUPPLY CHAIN" EXPORT (2-tab raw Excel, no formulas)
   ============================================================ */
function buildMalaccaSupplyChain(sections, fileLabel) {
  const fabricRows = [['Fabric category', 'Fabric code', 'Reference no', 'Description', 'Supplier']];
  for (const r of (sections['01 - Fabric'] || [])) {
    fabricRows.push([r.componentName, malaccaLeadingNumber(r.material), malaccaCleanText(r.referenceNo), r.material, r.supplier]);
  }

  const trimsRows = [['Item name', 'Item code', 'Reference no', 'Size', 'Description', 'Supplier']];
  for (const [secKey, items] of Object.entries(sections)) {
    if (secKey === '01 - Fabric') continue;
    for (const r of items) {
      trimsRows.push([r.materialType, malaccaLeadingNumber(r.material), malaccaCleanText(r.referenceNo), r.size, r.material, r.supplier]);
    }
  }

  const wsFabric = XLSX.utils.aoa_to_sheet(fabricRows);
  wsFabric['!cols'] = [{ wch: 20 }, { wch: 12 }, { wch: 16 }, { wch: 60 }, { wch: 24 }];
  const wsTrims = XLSX.utils.aoa_to_sheet(trimsRows);
  wsTrims['!cols'] = [{ wch: 20 }, { wch: 12 }, { wch: 16 }, { wch: 12 }, { wch: 60 }, { wch: 24 }];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, wsFabric, 'Fabric');
  XLSX.utils.book_append_sheet(wb, wsTrims, 'Trims');
  XLSX.writeFile(wb, `${fileLabel || 'malacca'}_SupplyChain.xlsx`);
}

/* ============================================================
   MALACCA — GENERATE CBD (merge into the CBD costing format)
   ============================================================ */
// Section order as it appears top-to-bottom in the CBD table, and which
// tech-pack field feeds the "component name" column (B) for each — Fabric
// uses its own Component Name field, every other section uses Material Type.
// Common/standard prices, keyed by item code (the leading number of the
// extracted material text, e.g. "1946 No Material STD Silica Gel" -> code
// "1946"). Prices are written exactly as given — as a live formula where
// the chart shows one (e.g. "=0.1/12"), or as a plain number otherwise.
const MALACCA_PRICE_CHART = {
  '1946':  { price: { formula: '0.1/12' },  comments: 'Universal' },
  '1423':  { price: { formula: '80/1000' }, comments: 'Adzi' },
  '1892':  { price: 1.52,                   comments: '' },
  '1534':  { price: 0.2,                    comments: 'Bengal' },
  '1533':  { price: 0.2,                    comments: 'Bengal' },
  '8018':  { price: { formula: '5.4/1000' },  comments: 'Adzi' },
  '5217':  { price: { formula: '10/1000' },   comments: 'Adzi' },
  '5787':  { price: { formula: '10/1000' },   comments: 'Adzi' },
  '19603': { price: { formula: '10/1000' },   comments: 'Adzi' },
  '1900':  { price: { formula: '10/1000' },   comments: 'Adzi' },
  '1535':  { price: { formula: '36.5/1000' }, comments: 'Adzi' },
  '3382':  { price: { formula: '8/1000' },    comments: 'Adzi' },
  '1884':  { price: { formula: '8/5000' },    comments: 'Makstring' },
  '1885':  { price: { formula: '7/5000' },    comments: '' },
};

const MALACCA_CBD_SECTIONS = [
  { key: '01 - Fabric',             nameField: 'componentName', hasSize: false },
  { key: '02 - Trims',              nameField: 'materialType',  hasSize: true },
  { key: '03 - Decoration',         nameField: 'materialType',  hasSize: true },
  { key: '04 - Product Packaging',  nameField: 'materialType',  hasSize: true },
  { key: '05 - Shipping & Packing', nameField: 'materialType',  hasSize: true },
];
const MALACCA_CBD_MAXCOL = 74; // column BV
const MALACCA_CBD_FORMULA_COLS = ['K', 'O', 'P'];

function findMalaccaSectionRange(ws, sectionLabel, scanEnd) {
  let first = null, last = null;
  for (let r = 29; r <= scanEnd; r++) {
    if (ws.getCell(r, 1).value === sectionLabel) {
      if (first === null) first = r;
      last = r;
    }
  }
  return { first, last };
}

function malaccaParseNum(v) {
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
}

async function buildMalaccaCBD(templateArrayBuffer, sections, styleNumber, coverInfo) {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(templateArrayBuffer.slice(0));
  const ws = workbook.worksheets[0];

  // The CBD template ships with the header row frozen (view state:
  // 'frozen', pane at A28). Strip the freeze/pane info so the generated
  // file opens with no frozen rows or columns, keeping any other view
  // settings (gridlines, zoom, etc.) intact.
  ws.views = (ws.views || []).map(v => {
    const { state, xSplit, ySplit, topLeftCell, activePane, pane, ...rest } = v;
    return rest;
  });

  // The CBD template ships with a garment placeholder picture baked in —
  // not needed, strip it out entirely.
  ws._media = [];

  // Top-left header cells: Brand (B4), Style Name (B6, number only),
  // Gender (B7), Age (B8), Subclass (B9, description only), Production
  // Manager (B12) — only overwrite when we actually extracted a value, so
  // a failed/partial extraction never blanks out the template.
  if (coverInfo) {
    if (coverInfo.brand) ws.getCell('B4').value = coverInfo.brand;
    if (coverInfo.styleNo) ws.getCell('B6').value = coverInfo.styleNo;
    if (coverInfo.gender) ws.getCell('B7').value = coverInfo.gender;
    if (coverInfo.age) ws.getCell('B8').value = coverInfo.age;
    if (coverInfo.subclass) ws.getCell('B9').value = coverInfo.subclass;
    if (coverInfo.productionManager) ws.getCell('B12').value = coverInfo.productionManager;
  }

  normalizeFormulas(ws, ws.rowCount, MALACCA_CBD_MAXCOL);

  // process bottom-to-top so inserting rows in a lower section never shifts
  // a section still queued for processing above it
  const order = [...MALACCA_CBD_SECTIONS].reverse();
  let maxSheetRow = ws.rowCount;
  const counts = {};

  for (const cfg of order) {
    const items = sections[cfg.key] || [];
    counts[cfg.key] = items.length;
    let { first, last } = findMalaccaSectionRange(ws, cfg.key, Math.max(maxSheetRow, 69));
    if (first === null) continue; // section doesn't exist in this template — skip (not handled)

    const capacity = last - first + 1;
    const needed = items.length;
    const amount = needed - capacity;

    if (amount > 0) {
      const insertAt = last;
      const blankRows = Array.from({ length: amount }, () => []);
      ws.spliceRows(insertAt, 0, ...blankRows);
      shiftWholeSheetFormulas(ws, insertAt, amount, maxSheetRow + amount, MALACCA_CBD_MAXCOL);
      for (let i = 0; i < amount; i++) {
        const newRow = insertAt + i;
        copyRowStyle(ws, insertAt + amount, newRow, MALACCA_CBD_MAXCOL);
        copyRowFormulas(ws, insertAt + amount, newRow, MALACCA_CBD_FORMULA_COLS);
      }
      maxSheetRow += amount;
      last += amount;
    } else if (amount < 0) {
      // fewer items than the section's existing row capacity — remove the
      // excess rows outright (rather than just blanking their values) so
      // no empty rows are left behind in the generated sheet.
      const removeCount = -amount;
      const removeAt = first + needed;
      ws.spliceRows(removeAt, removeCount);
      shiftWholeSheetFormulas(ws, removeAt, amount, maxSheetRow + amount, MALACCA_CBD_MAXCOL);
      maxSheetRow += amount; // amount is negative here, so this shrinks
      last += amount;
    }

    items.forEach((item, i) => {
      const r = first + i;
      ws.getCell(r, 1).value = cfg.key;                         // A - Section
      ws.getCell(r, 2).value = item[cfg.nameField] || '';       // B - Component Name
      ws.getCell(r, 3).value = item.placement || '';            // C - Placement
      ws.getCell(r, 4).value = item.material || '';             // D - Material
      ws.getCell(r, 5).value = item.supplier || '';             // E - Material Supplier
      ws.getCell(r, 6).value = 'USD';                           // F - MS Currency
      ws.getCell(r, 12).value = malaccaParseNum(item.consumption); // L - Consumption
      ws.getCell(r, 13).value = item.articleUOM || '';          // M - Article UOM
      // N - LOSS % (wastage): 10% for thread items, 3% for everything else
      const isThread = /thread/i.test(item.materialType || '') || /thread/i.test(item.componentName || '') || /thread/i.test(item.material || '');
      ws.getCell(r, 14).value = isThread ? 0.10 : 0.03;
      if (cfg.hasSize) ws.getCell(r, 29).value = item.size || ''; // AC - Size
      ws.getCell(r, 31).value = 'Yes';                          // AE - Include in PP?

      // Price chart match: PRICE OVR (I) as a number/formula, Comments-GS
      // (Q) as text — only written when the item's code is in the chart,
      // so unmatched items keep the template's own blank/default cells.
      const priceEntry = MALACCA_PRICE_CHART[malaccaLeadingNumber(item.material)];
      if (priceEntry) {
        const priceCell = ws.getCell(r, 9); // I - PRICE OVR
        priceCell.value = priceEntry.price;
        priceCell.numFmt = priceCell.numFmt && priceCell.numFmt !== 'General' ? priceCell.numFmt : '0.0000';
        if (priceEntry.comments) {
          const commentsCell = ws.getCell(r, 17); // Q - Comments-GS
          commentsCell.numFmt = '@'; // force text format
          commentsCell.value = priceEntry.comments;
        }
      }
    });
  }

  if (styleNumber) ws.name = String(styleNumber);

  const buffer = await workbook.xlsx.writeBuffer();
  return { buffer, counts };
}



/* ============================================================
   MALACCA — UI WIRING
   ============================================================ */
const malaccaView = document.getElementById('malaccaView');
document.getElementById('brandMalacca').addEventListener('click', () => {
  requestUnlock('malacca', () => {
    homeView.hidden = true;
    malaccaView.hidden = false;
  });
});
document.getElementById('backBtnMal').addEventListener('click', () => {
  malaccaView.hidden = true;
  homeView.hidden = false;
});

const dropzoneMal = document.getElementById('dropzoneMal');
const fileInputMal = document.getElementById('fileInputMal');
const filebarMal = document.getElementById('filebarMal');
const fileNameMalEl = document.getElementById('fileNameMal');
const clearFileMal = document.getElementById('clearFileMal');
const processBtnMal = document.getElementById('processBtnMal');
const processLabelMal = document.getElementById('processLabelMal');
const statusMal = document.getElementById('statusMal');
const resultsMal = document.getElementById('resultsMal');
const supplyChainBtnMal = document.getElementById('supplyChainBtnMal');
const cbdBtnMal = document.getElementById('cbdBtnMal');
const cbdLabelMal = document.getElementById('cbdLabelMal');
const cbdStatusMal = document.getElementById('cbdStatusMal');

let currentFileMal = null;
let currentMalSections = null;
let currentMalStyleNumber = null;
let currentMalCoverInfo = null;

function setStatusMal(msg, cls) {
  statusMal.textContent = msg;
  statusMal.className = 'status' + (cls ? ' ' + cls : '');
}

function setFileMal(file) {
  if (!file || file.type !== 'application/pdf') {
    setStatusMal('Please choose a PDF file.', 'err');
    return;
  }
  currentFileMal = file;
  fileNameMalEl.textContent = file.name;
  filebarMal.classList.add('show');
  setStatusMal('');
  resultsMal.classList.remove('show');
  currentMalSections = null;
  currentMalCoverInfo = null;
  processBtnMal.disabled = false;
}

dropzoneMal.addEventListener('dragover', e => { e.preventDefault(); dropzoneMal.classList.add('drag'); });
dropzoneMal.addEventListener('dragleave', () => dropzoneMal.classList.remove('drag'));
dropzoneMal.addEventListener('drop', e => {
  e.preventDefault(); dropzoneMal.classList.remove('drag');
  if (e.dataTransfer.files.length) setFileMal(e.dataTransfer.files[0]);
});
fileInputMal.addEventListener('change', e => {
  if (e.target.files.length) setFileMal(e.target.files[0]);
});
clearFileMal.addEventListener('click', e => {
  e.stopPropagation();
  currentFileMal = null; fileInputMal.value = '';
  filebarMal.classList.remove('show');
  resultsMal.classList.remove('show');
  currentMalSections = null;
  currentMalCoverInfo = null;
  setStatusMal('');
  processBtnMal.disabled = true;
});

function malaccaItemCount(sections) {
  return Object.values(sections).reduce((s, rows) => s + rows.length, 0);
}

// derive the style number from the uploaded filename (e.g.
// "154969_001_APDAW28Initial_..." -> "154969") — the tech pack's leading
// numeric token, consistent across this buyer's file naming.
function malaccaStyleFromFilename(name) {
  const m = (name || '').match(/^(\d+)/);
  return m ? m[1] : 'malacca';
}

processBtnMal.addEventListener('click', async () => {
  if (!currentFileMal) return;
  processBtnMal.disabled = true;
  processBtnMal.classList.add('loading');
  resultsMal.classList.remove('show');
  try {
    const { sections, styleNumber, coverInfo } = await extractMalaccaPdf(currentFileMal, (p, total) => {
      processLabelMal.textContent = `Scanning page ${p} / ${total}...`;
      setStatusMal(`Scanning page ${p} of ${total}...`);
    });
    currentMalSections = sections;
    currentMalStyleNumber = styleNumber || malaccaStyleFromFilename(currentFileMal.name);
    currentMalCoverInfo = coverInfo;
    const total = malaccaItemCount(sections);
    if (total === 0) {
      setStatusMal('No BOM line items were found in this tech pack.', 'err');
    } else {
      const summary = MALACCA_CBD_SECTIONS.map(c => `${c.key}: ${(sections[c.key] || []).length}`).join(', ');
      setStatusMal(`Done — ${total} items extracted. ${summary}.`, 'ok');
      resultsMal.classList.add('show');
    }
  } catch (err) {
    console.error(err);
    setStatusMal('Something went wrong reading this PDF: ' + err.message, 'err');
    currentMalSections = null;
    currentMalCoverInfo = null;
  } finally {
    processBtnMal.disabled = false;
    processBtnMal.classList.remove('loading');
    processLabelMal.textContent = 'Extract Tech Pack';
  }
});

supplyChainBtnMal.addEventListener('click', () => {
  if (!currentMalSections) return;
  buildMalaccaSupplyChain(currentMalSections, currentMalStyleNumber);
});

cbdBtnMal.addEventListener('click', async () => {
  if (!currentMalSections) return;
  cbdBtnMal.disabled = true;
  cbdBtnMal.classList.add('loading');
  cbdLabelMal.textContent = 'Building CBD file...';
  cbdStatusMal.textContent = '';
  cbdStatusMal.className = 'status';
  try {
    const templateBuffer = base64ToArrayBuffer(MALACCA_TEMPLATE_B64);
    const { buffer, counts } = await buildMalaccaCBD(templateBuffer, currentMalSections, currentMalStyleNumber, currentMalCoverInfo);
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${currentMalStyleNumber}_CS.xlsx`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    const parts = Object.entries(counts).map(([k, v]) => `${k}: ${v}`).join(' | ');
    cbdStatusMal.textContent = `Done — ${parts}`;
    cbdStatusMal.className = 'status ok';
  } catch (err) {
    console.error(err);
    cbdStatusMal.textContent = 'Something went wrong building the CBD file: ' + err.message;
    cbdStatusMal.className = 'status err';
  } finally {
    cbdBtnMal.disabled = false;
    cbdBtnMal.classList.remove('loading');
    cbdLabelMal.textContent = 'Generate CBD';
  }
});
